-- Run ONCE in Supabase SQL Editor (after update_bots.sql). Adds the 173 officially RETAINED 2026 players as an optional pool.
-- Retained list: iplt20.com "TATA IPL 2026 Player Retentions Announced" (Nov 15, 2025). Role / capped status / base price are CUSTOM estimates.
alter table players add column if not exists retained boolean default false;
do $$ begin
  if not exists(select 1 from players where retained) then update players set set_no=set_no+4; end if;  -- retained stars become sets 1-4
end $$;

drop function if exists create_room(text,text,text,text,int);
create function create_room(p_name text,p_owner text,p_team text,p_color text,p_max_set int default 99,p_retained boolean default true) returns text
language plpgsql security definer set search_path=public as $$
declare rid uuid; c text;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  loop c:=upper(substr(md5(random()::text||clock_timestamp()::text),1,6)); exit when not exists(select 1 from rooms where code=c); end loop;
    select rid,id,row_number() over(order by set_no,list_no),base_lakh from players where set_no<=p_max_set and (p_retained or not retained);
  return c;
end $$;
